import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.*;
/** Full source parsing is still required; this hook supplies only the exact old identity. */
public class TimedAfterSourceContractTest {
 private String s(String n)throws Exception{return Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once",n+".java")).replace("\r\n","\n");}
 @Test public void onlyBusinessAfterCanTakeReturnedAnchor()throws Exception{String r=s("CaptureSessionRuntime");assertTrue(r.contains("rootMode==RootCaptureScope.Mode.BUSINESS&&cardPhase==NativeRewardCardSession.Phase.AFTER&&autonomousRun!=null"));assertTrue(r.contains("rootTimedAfterAnchor=autonomousRun.timedAfterSource()"));assertTrue(r.contains("rootTimedAfterAnchor==null?rootPreflightMetadata.readPre("));assertTrue(r.contains("rootPreflightMetadata.readPreTimedReturn("));}
 @Test public void postRequiresStillCurrentExactAnchorAndFreshFullSource()throws Exception{String r=s("CaptureSessionRuntime");int start=r.indexOf("private boolean acceptRootSourcePostcheck()"),end=r.indexOf("static boolean rootResourcesAfterPostcheck",start);String p=r.substring(start,end);for(String token:new String[]{"currentAnchor==null||!rootTimedAfterAnchor.sameSource(currentAnchor)","readPostTimedReturn(","rootPreflightBefore.sameSource(after.ready())","after.ready().fresh(SystemClock.elapsedRealtime())","ReviewBingNavigation.knownClean()","rootPreflightFresh()","activity.hiddenWithSoleTask()"})assertTrue(token,p.contains(token));}
 @Test public void originalBudgetsAndActualCleanPostPermitRemain()throws Exception{String r=s("CaptureSessionRuntime");assertTrue(r.contains("int limit=3; // Exact per-phase source budget"));assertTrue(r.contains("pre>=3"));assertTrue(r.contains("post=true;return pre>0"));assertTrue(r.contains("run.rootCleanReceipt.clean()&&run.rootCleanReceipt.liveTransport()"));assertTrue(r.contains("rootPreflightSourceConfirmed&&resources&&rootCurrent()"));}
}
